CREATE TABLE IF NOT EXISTS gis_phase354_dataset_inventory (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_id TEXT, provider TEXT, feature_count BIGINT NOT NULL DEFAULT 0, state_count BIGINT NOT NULL DEFAULT 0, parent_count BIGINT NOT NULL DEFAULT 0, valid_geometry_count BIGINT NOT NULL DEFAULT 0, empty_geometry_count BIGINT NOT NULL DEFAULT 0, srid_count BIGINT NOT NULL DEFAULT 0, min_feature_key TEXT, max_feature_key TEXT, inventory_status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_id,provider));